// src/podkop/tabs/diagnostic/checks/updateCheckStore.ts
function updateCheckStore(check, minified) {
  const diagnosticsChecks = store.get().diagnosticsChecks;
  const other = diagnosticsChecks.filter((item) => item.code !== check.code);
  const smallCheck = {
    ...check,
    items: check.items.filter((item) => item.state !== "success")
  };
  const targetCheck = minified ? smallCheck : check;
  store.set({
    diagnosticsChecks: [...other, targetCheck]
  });
}

// src/podkop/tabs/diagnostic/helpers/getMeta.ts
function getMeta({ allGood, atLeastOneGood }) {
  if (allGood) {
    return {
      state: "success",
      description: _("Checks passed")
    };
  }
  if (atLeastOneGood) {
    return {
      state: "warning",
      description: _("Issues detected")
    };
  }
  return {
    state: "error",
    description: _("Checks failed")
  };
}

// src/podkop/tabs/diagnostic/checks/runDnsCheck.ts
function serverName(server) {
  if (server.type !== "provider") return `${server.server} [${server.type}]`;
  return server.providers?.length ? _("The provider's DNS: %s").format(server.providers.join(", ")) : _("The provider's DNS: the router knows none now");
}
function serverItem(server, key) {
  if (server.status)
    return { state: "success", key, value: serverName(server) };
  if (!server.refusal)
    return { state: "error", key, value: serverName(server) };
  return {
    state: "warning",
    key,
    value: `${serverName(server)} \u2014 ${_("replies %s").format(server.refusal)}`
  };
}
function dnsServerItems(servers, mode) {
  if (servers.length === 1) {
    return [serverItem(servers[0], _("Main DNS"))];
  }
  const asked = mode === "fastest" ? _("the fastest first") : _("in their order");
  return servers.map(
    (server, index) => serverItem(
      server,
      index === 0 ? _("DNS %d of %d, %s").format(index + 1, servers.length, asked) : _("DNS %d").format(index + 1)
    )
  );
}
async function runDnsCheck() {
  const { order, title, code } = DIAGNOSTICS_CHECKS_MAP.DNS;
  updateCheckStore({
    order,
    code,
    title,
    description: _("Checking, please wait"),
    state: "loading",
    items: []
  });
  const dnsChecks = await PodkopShellMethods.checkDNSAvailable();
  if (!dnsChecks.success) {
    updateCheckStore({
      order,
      code,
      title,
      description: _("Cannot receive checks result"),
      state: "error",
      items: []
    });
    throw new Error("DNS checks failed");
  }
  const data = dnsChecks.data;
  const servers = data.dns_servers?.length ? data.dns_servers : [
    {
      type: data.dns_type,
      server: data.dns_server,
      status: data.dns_status
    }
  ];
  const allGood = Boolean(data.dns_on_router) && Boolean(data.dhcp_config_status) && Boolean(data.bootstrap_dns_status) && servers.every((server) => Boolean(server.status));
  const atLeastOneGood = Boolean(data.dns_on_router) || Boolean(data.dhcp_config_status) || Boolean(data.bootstrap_dns_status) || Boolean(data.dns_status);
  const { state, description } = getMeta({ atLeastOneGood, allGood });
  updateCheckStore({
    order,
    code,
    title,
    description,
    state,
    items: [
      ...insertIf(
        servers.some(
          (server) => server.type === "doh" || server.type === "dot"
        ) || !data.bootstrap_dns_status,
        [
          {
            state: data.bootstrap_dns_status ? "success" : "error",
            key: _("Bootsrap DNS"),
            value: data.bootstrap_dns_server
          }
        ]
      ),
      ...dnsServerItems(servers, data.dns_mode),
      {
        state: data.dns_on_router ? "success" : "error",
        key: _("DNS on router"),
        value: ""
      },
      {
        state: data.dhcp_config_status ? "success" : "error",
        key: _("DHCP has DNS server"),
        value: ""
      }
    ]
  });
  if (!atLeastOneGood) {
    throw new Error("DNS checks failed");
  }
}

// src/podkop/tabs/diagnostic/checks/runSingBoxCheck.ts
async function runSingBoxCheck() {
  const { order, title, code } = DIAGNOSTICS_CHECKS_MAP.SINGBOX;
  updateCheckStore({
    order,
    code,
    title,
    description: _("Checking, please wait"),
    state: "loading",
    items: []
  });
  const singBoxChecks = await PodkopShellMethods.checkSingBox();
  if (!singBoxChecks.success) {
    updateCheckStore({
      order,
      code,
      title,
      description: _("Cannot receive checks result"),
      state: "error",
      items: []
    });
    throw new Error("Podkop checks failed");
  }
  const data = singBoxChecks.data;
  const running = Boolean(data.sing_box_process_running);
  const listening = Boolean(data.sing_box_ports_listening);
  const allGood = running && listening;
  const atLeastOneGood = running || listening;
  const { state, description } = getMeta({ atLeastOneGood, allGood });
  updateCheckStore({
    order,
    code,
    title,
    description,
    state,
    items: [
      {
        state: running ? "success" : "error",
        key: _("Podkop is running"),
        value: ""
      },
      {
        state: listening ? "success" : "error",
        key: _(
          "Podkop listens for the DNS of the LAN and the transparent proxy"
        ),
        value: ""
      }
    ]
  });
  if (!running) {
    throw new Error("Podkop checks failed");
  }
}

// src/podkop/tabs/diagnostic/checks/runNftCheck.ts
async function runNftCheck(label) {
  const { order, title, code } = DIAGNOSTICS_CHECKS_MAP.NFT;
  updateCheckStore({
    order,
    code,
    title,
    description: _("Checking, please wait"),
    state: "loading",
    items: []
  });
  const nftablesChecks = await PodkopShellMethods.checkNftRules(label);
  if (!nftablesChecks.success) {
    updateCheckStore({
      order,
      code,
      title,
      description: _("Cannot receive checks result"),
      state: "error",
      items: []
    });
    throw new Error("Nftables checks failed");
  }
  const data = nftablesChecks.data;
  const allGood = Boolean(data.table_exist) && Boolean(data.rules_mangle_exist) && Boolean(data.rules_mangle_counters) && Boolean(data.rules_mangle_output_exist) && Boolean(data.rules_mangle_output_counters) && Boolean(data.rules_proxy_exist) && Boolean(data.rules_proxy_counters) && !data.rules_other_mark_exist;
  const atLeastOneGood = Boolean(data.table_exist) || Boolean(data.rules_mangle_exist) || Boolean(data.rules_mangle_counters) || Boolean(data.rules_mangle_output_exist) || Boolean(data.rules_mangle_output_counters) || Boolean(data.rules_proxy_exist) || Boolean(data.rules_proxy_counters) || !data.rules_other_mark_exist;
  const { state, description } = getMeta({ atLeastOneGood, allGood });
  updateCheckStore({
    order,
    code,
    title,
    description,
    state,
    items: [
      {
        state: data.table_exist ? "success" : "error",
        key: _("Table exist"),
        value: ""
      },
      {
        state: data.rules_mangle_exist ? "success" : "error",
        key: _("Rules mangle exist"),
        value: ""
      },
      {
        state: data.rules_mangle_counters ? "success" : "error",
        key: _("Rules mangle counters"),
        value: ""
      },
      {
        state: data.rules_mangle_output_exist ? "success" : "error",
        key: _("Rules mangle output exist"),
        value: ""
      },
      {
        state: data.rules_mangle_output_counters ? "success" : "error",
        key: _("Rules mangle output counters"),
        value: ""
      },
      {
        state: data.rules_proxy_exist ? "success" : "error",
        key: _("Rules proxy exist"),
        value: ""
      },
      {
        state: data.rules_proxy_counters ? "success" : "error",
        key: _("Rules proxy counters"),
        value: ""
      },
      {
        state: !data.rules_other_mark_exist ? "success" : "warning",
        key: !data.rules_other_mark_exist ? _("No other marking rules found") : _("Additional marking rules found"),
        value: ""
      }
    ]
  });
  if (!atLeastOneGood) {
    throw new Error("Nftables checks failed");
  }
}

// src/podkop/tabs/diagnostic/checks/runFakeIPCheck.ts
async function runFakeIPCheck(label) {
  const { order, title, code } = DIAGNOSTICS_CHECKS_MAP.FAKEIP;
  updateCheckStore({
    order,
    code,
    title,
    description: _("Checking, please wait"),
    state: "loading",
    items: []
  });
  const [routerFakeIPResponse, browserResponse] = await Promise.all([
    PodkopShellMethods.checkFakeIP(),
    PodkopShellMethods.checkFakeIPClient(label)
  ]);
  const checks = {
    router: routerFakeIPResponse.success && routerFakeIPResponse.data.fakeip,
    browserDNS: browserResponse.success && browserResponse.data.dns,
    browserFakeIP: browserResponse.success && browserResponse.data.connection
  };
  const allGood = checks.router && checks.browserDNS && checks.browserFakeIP;
  const atLeastOneGood = checks.router || checks.browserDNS || checks.browserFakeIP;
  const { state, description } = getMeta({ atLeastOneGood, allGood });
  updateCheckStore({
    order,
    code,
    title,
    description,
    state,
    items: [
      {
        state: checks.router ? "success" : "warning",
        key: checks.router ? _("Router DNS is routed through podkop") : _("Router DNS is not routed through podkop"),
        value: ""
      },
      {
        state: checks.browserDNS ? "success" : "error",
        key: checks.browserDNS ? _("Browser DNS is routed through podkop") : _("Browser DNS is not routed through podkop"),
        value: ""
      },
      {
        state: checks.browserFakeIP ? "success" : "error",
        key: checks.browserFakeIP ? _("Browser is using FakeIP correctly") : _("Browser is not using FakeIP"),
        value: ""
      }
    ]
  });
}

